window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-759e1e6e445de89a"]={"versions": [{"id": "FIG-759e1e6e445de89a", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd NvM_GetDataIndex</code>) im Kontext des AUTOSAR Basic Software Moduls NVRAM Manager (NvM). Das Diagramm stellt den synchronen Aufruf zur Ermittlung des aktuellen Datenindex eines Datensatz-basierten NVRAM-Blocks dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>SW Component</code> (aus dem Paket <code>Interaction Views</code>): Aufrufende Software-Komponente bzw. BSW-Modul (NvM-Nutzer).\n</li><li><code>NvM::NvM</code>: NVRAM Manager Modul der Basessoftware, gekennzeichnet mit dem Subsystem-/Verweis-Symbol.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Synchroner Funktionsaufruf: <code>NvM_GetDataIndex(BlockId, DataIndexPtr)</code>\n</li><li>Rückkehrnachricht: <code>NvM_GetDataIndex</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die <code>SW Component</code> setzt einen synchronen Aufruf <code>NvM_GetDataIndex(BlockId, DataIndexPtr)</code> an <code>NvM::NvM</code> ab.\n</li><li>Beim Empfang aktiviert sich der Ausführungsfokus auf der Lebenslinie von <code>NvM::NvM</code>.\n</li><li>Nach interner Verarbeitung und Bereitstellung des Indexwertes über den übergebenen Zeiger antwortet <code>NvM::NvM</code> mit einer gestrichelten Rückkehrnachricht <code>NvM_GetDataIndex</code> an die aufrufende Komponente, womit die synchrone Interaktion abgeschlossen ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der synchrone API-Dienst dient dem Abfragen des aktuellen Datenindex für NVRAM-Blöcke des Typs DATASET. Die Parameter <code>BlockId</code> und <code>DataIndexPtr</code> sind in dieser Fassung noch ohne formale AUTOSAR-Typbezeichner notiert. Die Rückkehrnachricht signalisiert die Beendigung des Funktionsaufrufs.</p>"}, {"id": "FIG-68ce776e133a65ca", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd NvM_GetDataIndex</code>) im Kontext des AUTOSAR Basic Software Moduls NVRAM Manager (NvM). Das Diagramm stellt den synchronen Aufruf zur Ermittlung des aktuellen Datenindex eines Datensatz-basierten NVRAM-Blocks dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>Generic Elements::NvM User</code>: Aufrufende Entität bzw. Nutzer des NVRAM Managers.\n</li><li><code>«module» NvM::NvM</code>: NVRAM-Manager-Basessoftwaremodul mit Stereotyp <code>«module»</code> und Verweis-Symbol.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Synchroner Aufruf: <code>NvM_GetDataIndex(BlockId,DataIndexPtr)</code>\n</li><li>Rückkehrnachricht: <code>NvM_GetDataIndex</code>\n</li></ul>\n<p class=\"fig-p\">Zusätzliche Annotation:</p>\n<ul class=\"fig-list\"><li>Notizblock mit den Feldern <code>Status: Proposed by TO as per NvM SWS 1.44</code>, <code>Description:</code>, <code>Comments:</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die <code>SW Component</code> setzt einen synchronen Aufruf <code>NvM_GetDataIndex(BlockId, DataIndexPtr)</code> an <code>NvM::NvM</code> ab.\n</li><li>Beim Empfang aktiviert sich der Ausführungsfokus auf der Lebenslinie von <code>NvM::NvM</code>.\n</li><li>Nach interner Verarbeitung und Bereitstellung des Indexwertes über den übergebenen Zeiger antwortet <code>NvM::NvM</code> mit einer gestrichelten Rückkehrnachricht <code>NvM_GetDataIndex</code> an die aufrufende Komponente, womit die synchrone Interaktion abgeschlossen ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der synchrone API-Dienst dient dem Auslesen des aktiven Datensatzindex für Dataset-Blöcke. Die Parameternamen <code>BlockId</code> und <code>DataIndexPtr</code> sind informell ohne C-Typen angegeben. Ein Notizfeld dokumentiert den Standardisierungsstatus als Vorschlag gemäß NvM SWS 1.44.</p>"}, {"id": "FIG-291315ff6a86a732", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd NvM_GetDataIndex</code>) im Kontext des AUTOSAR Basic Software Moduls NVRAM Manager (NvM). Das Diagramm stellt den synchronen Aufruf zur Ermittlung des aktuellen Datenindex eines Datensatz-basierten NVRAM-Blocks dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>NvM User</code>: Aufrufende BSW- oder SWC-Entität.\n</li><li><code>«module» NvM</code>: NVRAM-Manager-Modul.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Synchroner Aufruf: <code>NvM_GetDataIndex(NvM_BlockIdType, uint8*)</code>\n</li><li>Rückkehrnachricht: <code>NvM_GetDataIndex()</code>\n</li></ul>\n<p class=\"fig-p\">Zusätzliche Annotation:</p>\n<ul class=\"fig-list\"><li>Notizblock mit <code>Status: Proposed by TO as per NvM SWS 1.44</code>, <code>Description:</code>, <code>Comments:</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>NvM User</code> ruft synchron die Funktion <code>NvM_GetDataIndex(NvM_BlockIdType, uint8*)</code> auf dem Modul <code>NvM</code> auf.\n</li><li>Der Ausführungsfokus geht auf die Lebenslinie von <code>NvM</code> über.\n</li><li><code>NvM</code> liefert das Ergebnis mit der Rückkehrnachricht <code>NvM_GetDataIndex()</code> zurück an den <code>NvM User</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der Parametertypen gemäß AUTOSAR-C-Schnittstelle: Blockidentifikator als <code>NvM_BlockIdType</code> und Zeiger auf den Speicherort des Datenindex als <code>uint8*</code>. Die synchrone Ausführung blockiert den Aufrufer bis zur Rückgabe.</p>"}, {"id": "FIG-51ea787438bc6909", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Sequenzdiagramm des AUTOSAR Basic Software Moduls NVRAM Manager (NvM) ohne äußeren Diagrammrahmen. Es beschreibt den synchronen Aufruf zur Abfrage des Datenindex eines Blocks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>NvM User</code>: Aufrufende Einheit.\n</li><li><code>«module» NvM</code>: NVRAM-Manager-Modul mit Verweis-Symbol.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Synchroner Aufruf: <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8**)</code>\n</li><li>Rückkehrnachricht: <code>NvM_GetDataIndex()</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>NvM User</code> ruft synchron <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8**)</code> am <code>NvM</code> auf.\n</li><li>Die Bearbeitung erfolgt synchron im Ausführungsbalken von <code>NvM</code>.\n</li><li>Der Aufruf kehrt mit der Rückkehrnachricht <code>NvM_GetDataIndex()</code> zum Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aufrufsignatur führt explizit den Rückgabetyp <code>Std_ReturnType</code> in der Parameterliste mit auf und deklariert den Index-Ausgabeparameter als Doppelzeiger (<code>uint8**</code>). Der Dienst wird synchron abgewickelt.</p>"}, {"id": "FIG-fe2855499e5e5857", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Sequenzdiagramm des AUTOSAR Basic Software Moduls NVRAM Manager (NvM) ohne äußeren Diagrammrahmen. Es beschreibt den synchronen Aufruf zur Abfrage des Datenindex eines Blocks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>NvM User</code>: Aufrufende Einheit.\n</li><li><code>«module» NvM</code>: NVRAM-Manager-Modul mit Verweis-Symbol.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Synchroner Aufruf: <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8*)</code>\n</li><li>Rückkehrnachricht: <code>NvM_GetDataIndex()</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>NvM User</code> ruft synchron <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8*)</code> am <code>NvM</code> auf.\n</li><li>Die Bearbeitung erfolgt synchron im Ausführungsbalken von <code>NvM</code>.\n</li><li>Der Aufruf kehrt mit der Rückkehrnachricht <code>NvM_GetDataIndex()</code> zum Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Signatur spezifiziert den Rückgabetyp <code>Std_ReturnType</code>, den Block-Identifikator <code>NvM_BlockIdType</code> sowie den Zeiger auf die Zielvariable des Datenindex als einfachen Zeiger <code>uint8*</code>. Die Ausführung ist rein synchron.</p>"}, {"id": "FIG-cbbeb3093b879b5d", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Sequenzdiagramm des AUTOSAR Basic Software Moduls NVRAM Manager (NvM) ohne äußeren Diagrammrahmen. Es beschreibt den synchronen Aufruf zur Abfrage des Datenindex eines Blocks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>NvM User</code>: Aufrufende Einheit.\n</li><li><code>«module» NvM</code>: NVRAM-Manager-Modul mit Verweis-Symbol.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Synchroner Aufruf: <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8*)</code>\n</li><li>Rückkehrnachricht: <code>NvM_GetDataIndex()</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>NvM User</code> ruft synchron <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8*)</code> am <code>NvM</code> auf.\n</li><li>Die Bearbeitung erfolgt synchron im Ausführungsbalken von <code>NvM</code>.\n</li><li>Der Aufruf kehrt mit der Rückkehrnachricht <code>NvM_GetDataIndex()</code> zum Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Signatur spezifiziert den Rückgabetyp <code>Std_ReturnType</code>, den Block-Identifikator <code>NvM_BlockIdType</code> sowie den Zeiger auf die Zielvariable des Datenindex als einfachen Zeiger <code>uint8*</code>. Die Ausführung ist rein synchron.</p>"}, {"id": "FIG-bcdc94d2220f9dff", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Sequenzdiagramm des AUTOSAR Basic Software Moduls NVRAM Manager (NvM) ohne äußeren Diagrammrahmen. Es beschreibt den synchronen Aufruf zur Abfrage des Datenindex eines Blocks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>NvM User</code>: Aufrufende Einheit.\n</li><li><code>«module» NvM</code>: NVRAM-Manager-Modul mit Verweis-Symbol.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Synchroner Aufruf: <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8**)</code>\n</li><li>Rückkehrnachricht: <code>NvM_GetDataIndex()</code> (mit Zeilenumbruch vor den Klammern)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>NvM User</code> ruft synchron <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8**)</code> am <code>NvM</code> auf.\n</li><li>Die Bearbeitung erfolgt synchron im Ausführungsbalken von <code>NvM</code>.\n</li><li>Der Aufruf kehrt mit der Rückkehrnachricht <code>NvM_GetDataIndex ()</code> zum Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Signatur weist den Zeiger auf den Datenindex als Doppelzeiger <code>uint8**</code> aus, kombiniert mit <code>Std_ReturnType</code> und <code>NvM_BlockIdType</code>. Die Abwicklung erfolgt synchron.</p>"}, {"id": "FIG-3c85189a3946bad2", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Sequenzdiagramm des AUTOSAR Basic Software Moduls NVRAM Manager (NvM) ohne äußeren Diagrammrahmen. Es beschreibt den synchronen Aufruf zur Abfrage des Datenindex eines Blocks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>NvM User</code>: Aufrufende Einheit.\n</li><li><code>«module» NvM</code>: NVRAM-Manager-Modul mit Verweis-Symbol.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Synchroner Aufruf: <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8**)</code>\n</li><li>Rückkehrnachricht: <code>NvM_GetDataIndex()</code> (mit Zeilenumbruch vor den Klammern)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>NvM User</code> ruft synchron <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8**)</code> am <code>NvM</code> auf.\n</li><li>Die Bearbeitung erfolgt synchron im Ausführungsbalken von <code>NvM</code>.\n</li><li>Der Aufruf kehrt mit der Rückkehrnachricht <code>NvM_GetDataIndex ()</code> zum Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Signatur weist den Zeiger auf den Datenindex als Doppelzeiger <code>uint8**</code> aus, kombiniert mit <code>Std_ReturnType</code> und <code>NvM_BlockIdType</code>. Die Abwicklung erfolgt synchron.</p>"}, {"id": "FIG-35ac07d7c6a6e43a", "releases": ["R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Sequenzdiagramm des AUTOSAR Basic Software Moduls NVRAM Manager (NvM) ohne äußeren Diagrammrahmen. Es beschreibt den synchronen Aufruf zur Abfrage des Datenindex eines Blocks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>NvM User</code>: Aufrufende Einheit.\n</li><li><code>«module» NvM</code>: NVRAM-Manager-Modul mit Verweis-Symbol.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Synchroner Aufruf: <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8**)</code>\n</li><li>Rückkehrnachricht: <code>NvM_GetDataIndex()</code> (mit Zeilenumbruch vor den Klammern)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>NvM User</code> ruft synchron <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8**)</code> am <code>NvM</code> auf.\n</li><li>Die Bearbeitung erfolgt synchron im Ausführungsbalken von <code>NvM</code>.\n</li><li>Der Aufruf kehrt mit der Rückkehrnachricht <code>NvM_GetDataIndex ()</code> zum Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Signatur weist den Zeiger auf den Datenindex als Doppelzeiger <code>uint8**</code> aus, kombiniert mit <code>Std_ReturnType</code> und <code>NvM_BlockIdType</code>. Die Abwicklung erfolgt synchron.</p>"}], "trans": [{"from": "FIG-759e1e6e445de89a", "to": "FIG-68ce776e133a65ca", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Diagrammrahmen &amp; Metadaten</strong>: Kommentar-Notizfeld mit Statusvermerk (<code>Status: Proposed by TO as per NvM SWS 1.44</code>, <code>Description:</code>, <code>Comments:</code>) im unteren Bereich hinzugefügt.\n</li><li><strong>Lebenslinie Aufrufer</strong>: Umbenennung von <code>SW Component</code> (mit Namensraum-Zusatz <code>(from Interaction Views)</code>) zu <code>Generic Elements::NvM User</code>.\n</li><li><strong>Lebenslinie Ziel</strong>: Ergänzung des Stereotyps <code>«module»</code> über <code>NvM::NvM</code>.\n</li><li><strong>Signatur Aufruf</strong>: Entfernung des Leerzeichens nach dem Komma in <code>NvM_GetDataIndex(BlockId,DataIndexPtr)</code>.\n</li></ul>"}, {"from": "FIG-68ce776e133a65ca", "to": "FIG-291315ff6a86a732", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Signatur Aufruf</strong>: Spezifikation konkreter Datentypen statt generischer Bezeichner in <code>NvM_GetDataIndex(NvM_BlockIdType, uint8*)</code>.\n</li><li><strong>Lebenslinie Aufrufer</strong>: Vereinfachung des Namens von <code>Generic Elements::NvM User</code> zu <code>NvM User</code>.\n</li><li><strong>Lebenslinie Ziel</strong>: Entfernung des Paket-Präfix von <code>NvM::NvM</code> zu <code>NvM</code>.\n</li><li><strong>Rückkehrnachricht</strong>: Signaturbezeichnung von <code>NvM_GetDataIndex</code> zu <code>NvM_GetDataIndex()</code> präzisiert.\n</li></ul>"}, {"from": "FIG-291315ff6a86a732", "to": "FIG-51ea787438bc6909", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Signatur Aufruf</strong>: Signatur um Rückgabetyp erweitert und Zeigertyp geändert zu zweistufigem Zeiger: <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8**)</code>.\n</li><li><strong>Diagrammrahmen &amp; Metadaten</strong>: Entfall des äußeren UML-Rahmens (<code>sd NvM_GetDataIndex</code>) sowie des Notizblocks (<code>Status: Proposed by TO as per NvM SWS 1.44</code>).\n</li></ul>"}, {"from": "FIG-51ea787438bc6909", "to": "FIG-fe2855499e5e5857", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Signatur Aufruf</strong>: Parameter für den Datenindexzeiger von Doppelzeiger <code>uint8**</code> auf einfachen Zeiger korrigiert: <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8*)</code>.\n</li></ul>"}, {"from": "FIG-fe2855499e5e5857", "to": "FIG-cbbeb3093b879b5d", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cbbeb3093b879b5d", "to": "FIG-bcdc94d2220f9dff", "fr": "R4.3.1", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Signatur Aufruf</strong>: Parameter für den Datenindexzeiger von einfachem Zeiger <code>uint8*</code> zurück auf Doppelzeiger geändert: <code>NvM_GetDataIndex(Std_ReturnType, NvM_BlockIdType, uint8**)</code>.\n</li><li><strong>Rückkehrnachricht</strong>: Zeilenumbruch der Klammern unterhalb des Funktionsnamens zu <code>NvM_GetDataIndex \\n ()</code>.\n</li></ul>"}, {"from": "FIG-bcdc94d2220f9dff", "to": "FIG-3c85189a3946bad2", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3c85189a3946bad2", "to": "FIG-35ac07d7c6a6e43a", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
